	protected void emitFindAllHealthSystem( HealthSystem entity ) {
		LOGGER.info("handling emitFindAllHealthSystem" );
		
	    queryUpdateEmitter.emit(FindAllHealthSystemQuery.class,
	                            query -> true,
	                            entity);
	}

